<script setup>
import {ref,computed,onMounted} from 'vue';
import {Plus,Check,Trash2,Pencil,X,CalendarDays,ListTodo,Flag} from 'lucide-vue-next';
const props=defineProps(['api']);const tasks=ref([]),filter=ref('pending'),busy=ref(false),error=ref(''),editId=ref(null),showForm=ref(false);
const fresh=()=>({title:'',priority:'normal',due:'',done:false});const form=ref(fresh());const today=new Date().toLocaleDateString('sv-SE');
const remaining=computed(()=>tasks.value.filter(t=>!t.done).length),completed=computed(()=>tasks.value.filter(t=>t.done).length);
const visible=computed(()=>tasks.value.filter(t=>filter.value==='all'||filter.value==='done'?filter.value==='all'||t.done:filter.value==='today'?!t.done&&t.due===today:filter.value==='overdue'?!t.done&&t.due&&t.due<today:!t.done));
async function load(){try{tasks.value=await props.api('/todos');}catch(e){error.value=e.message;}}
async function act(fn){busy.value=true;error.value='';try{await fn();await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
function edit(t){editId.value=t?.id||null;form.value=t?{title:t.title,priority:t.priority,due:t.due||'',done:!!t.done}:fresh();showForm.value=true;}
async function save(){await act(async()=>{await props.api('/todos'+(editId.value?'/'+editId.value:''),{method:editId.value?'PUT':'POST',body:JSON.stringify({...form.value,due:form.value.due||null})});showForm.value=false;});}
function toggle(t){act(()=>props.api('/todos/'+t.id,{method:'PUT',body:JSON.stringify({title:t.title,priority:t.priority,due:t.due,done:!t.done})}));}
function remove(t){if(confirm('删除这条待办事项？'))act(()=>props.api('/todos/'+t.id,{method:'DELETE'}));}
onMounted(load);
</script>
<template><div class="page-title"><div><div class="eyebrow">SMALL STEPS, REAL PROGRESS</div><h1>把想做的，变成做过的<span class="green">。</span></h1><p>为今天留一点计划，也为完成留一点成就感。</p></div><button class="primary" @click="edit()"><Plus :size="18"/>添加待办</button></div><div class="todo-overview"><div><ListTodo :size="24"/><b>{{remaining}}</b><span>件事，等你一步步完成</span></div><div class="todo-progress"><span>{{completed}} / {{tasks.length}} 已完成</span><div><i :style="{width:(tasks.length?completed/tasks.length*100:0)+'%'}"></i></div></div></div><div class="filters"><div class="tabs"><button v-for="f in [['pending','待完成'],['today','今天'],['overdue','已逾期'],['done','已完成'],['all','全部']]" :class="{chosen:filter===f[0]}" @click="filter=f[0]">{{f[1]}}</button></div><span class="muted">{{visible.length}} 项</span></div><div v-if="error" class="error" role="alert">{{error}} <button @click="load">重试</button></div><div class="todo-list"><article v-for="t in visible" :key="t.id" class="todo-row" :class="{completed:t.done}"><button class="task-check" :class="{checked:t.done}" :aria-label="(t.done?'重新开启 ':'完成 ')+t.title" :disabled="busy" @click="toggle(t)"><Check v-if="t.done" :size="15"/></button><div class="task-info"><h3>{{t.title}}</h3><div><span :class="['priority',t.priority]"><Flag :size="11"/>{{{normal:'普通',high:'高优先级',low:'低优先级'}[t.priority]}}</span><span v-if="t.due" :class="{overdue:!t.done&&t.due<today}"><CalendarDays :size="12"/>{{t.due===today?'今天':t.due}}{{!t.done&&t.due<today?' · 已逾期':''}}</span><span v-else>未设截止日期</span></div></div><button class="icon-button" :disabled="busy" :aria-label="'编辑 '+t.title" @click="edit(t)"><Pencil :size="16"/></button><button class="icon-button" :disabled="busy" :aria-label="'删除 '+t.title" @click="remove(t)"><Trash2 :size="16"/></button></article><div v-if="!visible.length" class="empty panel"><Check :size="35"/><h3>{{filter==='done'?'每个小小的完成，都值得记录':'此刻，一切从容'}}</h3><p>写下一件具体的小事，从这里迈出下一步。</p><button class="secondary" @click="edit()"><Plus :size="16"/>添加一个小目标</button></div></div><div v-if="showForm" class="modal-backdrop" @click.self="showForm=false"><form class="todo-dialog" @submit.prevent="save"><div class="section-top"><div><div class="eyebrow">ONE THING AT A TIME</div><h2>{{editId?'调整计划':'下一步，想做什么？'}}</h2></div><button type="button" class="icon-button" aria-label="关闭待办编辑" @click="showForm=false"><X/></button></div><label>待办事项<input v-model="form.title" maxlength="300" required placeholder="例如：读完响应式原理并写一篇笔记"/></label><div class="form-row"><label>截止日期<input type="date" v-model="form.due"/></label><label>优先级<select v-model="form.priority"><option value="normal">普通</option><option value="high">高优先级</option><option value="low">低优先级</option></select></label></div><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy||!form.title.trim()">{{busy?'保存中…':'保存待办'}}<Check :size="16"/></button></form></div></template>
